/bin/zsh -lc 'rtk sqlite3 -header -column /tmp/jobbot-chg146-r5-live-crawl_observations.sqlite3 "
SELECT COUNT(*) AS rows,COUNT(DISTINCT platform) AS platforms,COUNT(DISTINCT source_job_id) AS source_jobs,MIN(observed_at) AS first_observed,MAX(observed_at) AS last_observed FROM crawl_observations;
SELECT platform,source_job_id,LENGTH(normalized_card_json) AS card_json_bytes,LENGTH(detail_job_json) AS detail_json_bytes,content_completeness,source_build,schema_version FROM crawl_observations ORDER BY platform,source_job_id;
SELECT version,name,applied_at FROM observation_schema ORDER BY version;
"'

/bin/zsh -lc 'rtk sqlite3 -header -column /tmp/jobbot-chg146-r5-glassdoor21-crawl_observations.sqlite3 "
