/bin/zsh -lc "rtk sqlite3 -header -column /tmp/jobbot-chg146-r5-glassdoor21-ledger.sqlite3 \"
SELECT browser_run_id,version,mode,platform,status,started_at,completed_at,jobs_recorded,tasks_completed,tasks_challenged,tasks_incomplete,active_worker_count,worker_generation,last_error FROM browser_runs;
SELECT platform,worker_id,worker_generation,worker_status,worker_started_at,worker_heartbeat_at,readiness_state,auth_status,chrome_available,owned_window,window_id,search_tab_id,window_state,current_task_id,tasks_completed,tasks_challenged,tasks_incomplete,jobs_recorded FROM browser_platform_runs ORDER BY platform;
SELECT event_type,COUNT(*) AS n,MIN(event_at) AS first_at,MAX(event_at) AS last_at FROM browser_events GROUP BY event_type ORDER BY first_at;
SELECT COUNT(*) AS detail_page_navigations FROM browser_events WHERE event_type='detail_navigation';
SELECT source_site,source_job_id,source_url,identity_status,detail_status,content_state,detail_read,card_metadata FROM source_occurrences JOIN jobs ON jobs.job_id=source_occurrences.job_id;
\""

/bin/zsh -lc "rtk sqlite3 -header -column /tmp/jobbot-chg146-r5-live-ledger.sqlite3 \"
SELECT browser_run_id,version,mode,platform,status,started_at,completed_at,jobs_recorded,tasks_completed,tasks_challenged,tasks_incomplete,active_worker_count,worker_generation,last_error FROM browser_runs;
SELECT platform,worker_id,worker_generation,worker_status,worker_started_at,worker_heartbeat_at,readiness_state,auth_status,chrome_available,owned_window,window_id,search_tab_id,window_state,current_task_id,tasks_completed,tasks_challenged,tasks_incomplete,jobs_recorded FROM browser_platform_runs ORDER BY platform;
SELECT event_type,COUNT(*) AS n,MIN(event_at) AS first_at,MAX(event_at) AS last_at FROM browser_events GROUP BY event_type ORDER BY first_at;
SELECT COUNT(*) AS detail_page_navigations FROM browser_events WHERE event_type='detail_navigation';
SELECT COUNT(*) AS pane_events FROM browser_events WHERE event_type IN ('detail_diagnostics','detail_read');
SELECT COUNT(*) AS card_events FROM browser_events WHERE event_type IN ('card_persisted','cards_persisted','card_extracted');
SELECT COUNT(*) AS begin_events FROM browser_events WHERE event_type='begin_run';
\""

/bin/zsh -lc 'rtk sqlite3 -header -column /tmp/jobbot-chg146-r5-glassdoor21-ledger.sqlite3 "
SELECT so.source_site,so.source_job_id,so.source_url,so.apply_url,LENGTH(j.description) AS description_length,j.content_state,j.description_state,j.canonical_url,j.first_seen,j.last_seen FROM source_occurrences so JOIN jobs j ON j.job_id=so.job_id;
SELECT version,name,applied_at FROM schema_migrations ORDER BY version;
"'

/bin/zsh -lc "rtk sqlite3 -header -column /tmp/jobbot-chg146-r5-glassdoor21-ledger.sqlite3 \"
SELECT event_type,event_at,substr(payload_json,1,1100) AS payload FROM browser_events WHERE event_type IN ('worker_window_created','worker_window_bound','platform_readiness','detail_diagnostics','detail_read','job_recorded','result_discovered','result_batch') ORDER BY event_at,event_id;
\""

/bin/zsh -lc 'rtk sqlite3 -header -column /tmp/jobbot-chg146-r5-live-ledger.sqlite3 "
SELECT version,name,applied_at FROM schema_migrations ORDER BY version;
SELECT source_site,COUNT(*) AS n FROM source_occurrences GROUP BY source_site;
SELECT COUNT(*) AS jobs,COUNT(DISTINCT canonical_url) AS canonical_urls FROM jobs;
SELECT COUNT(*) AS duplicate_occurrence_keys FROM (SELECT occurrence_key,COUNT(*) n FROM source_occurrences GROUP BY occurrence_key HAVING n>1);
"'

